11	    public static int cutRod(int[] pricesByLength, int rodLength) {
12	        validatePriceTable(pricesByLength);
13	        validateRodLength(pricesByLength, rodLength);
14	
15	        int[] maxRevenue = new int[rodLength + 1];
16	        maxRevenue[SENTINEL_INDEX] = EMPTY_ROD_REVENUE;
17	
18	        for (int currentLength = FIRST_SELLABLE_LENGTH; currentLength <= rodLength; currentLength++) {
19	            maxRevenue[currentLength] = bestRevenueForLength(pricesByLength, maxRevenue, currentLength);
20	        }
21	
22	        return maxRevenue[rodLength];
23	    }
