31	    private static void validateRodLength(int[] pricesByLength, int rodLength) {
32	        if (rodLength < 0 || rodLength >= pricesByLength.length) {
33	            throw new IllegalArgumentException("rodLength must be within the pricesByLength table");
34	        }
35	    }
