37	    private static int bestRevenueForLength(int[] pricesByLength, int[] maxRevenue, int currentLength) {
38	        int bestRevenue = EMPTY_ROD_REVENUE;
39	
40	        for (int firstCutLength = FIRST_SELLABLE_LENGTH; firstCutLength <= currentLength; firstCutLength++) {
41	            int remainingLength = currentLength - firstCutLength;
42	            int revenue = pricesByLength[firstCutLength] + maxRevenue[remainingLength];
43	            bestRevenue = Math.max(bestRevenue, revenue);
44	        }
45	
46	        return bestRevenue;
47	    }
